int lower_bound(int** fruits, int fruitsSize, int target) {
    int left = 0, right = fruitsSize;
    while (left < right) {
        int mid = (left + right) / 2;
        if (fruits[mid][0] < target)
            left = mid + 1;
        else
            right = mid;
    }
    return left;
}

