        // so rightPos <= leftPos + (k - (startPos - leftPos))
        int maxRightPos = leftPos + (k - (startPos - leftPos));
        if (maxRightPos < leftPos) continue; // no steps left for right side

        // find right boundary index: first fruit position > maxRightPos
        int r = lower_bound(fruits, fruitsSize, maxRightPos + 1) - 1;
        if (r < l) continue;

        // sum fruits from l to r
        long long sum = prefix[r+1] - prefix[l];
        if (sum > ans) ans = (int)sum;
    }

    // Strategy 2: go right first, then left
    for (int r = startIndex; r < fruitsSize; r++) {
        int rightPos = fruits[r][0];
        // steps = (rightPos - startPos) + (rightPos - leftPos)
        // so leftPos >= rightPos - (k - (rightPos - startPos))
        int minLeftPos = rightPos - (k - (rightPos - startPos));
        if (minLeftPos > rightPos) continue; // no steps left for left side

        // find left boundary index: first fruit position >= minLeftPos
        int l = lower_bound(fruits, fruitsSize, minLeftPos);
        if (l > r) continue;

        long long sum = prefix[r+1] - prefix[l];
        if (sum > ans) ans = (int)sum;
    }

    // Also consider the case where we do not move at all (just harvest at startPos if any)
    // Check if startPos is exactly a fruit position
    int posIndex = lower_bound(fruits, fruitsSize, startPos);
    if (posIndex < fruitsSize && fruits[posIndex][0] == startPos) {
        if (fruits[posIndex][1] > ans) ans = fruits[posIndex][1];
    }

    free(prefix);
    return ans;
